[
  {
    "qid": "0008-t2i-1",
    "sample_id": "0008_斑铜制作技艺_ea5d134b.webp",
    "task": "t2i",
    "knowledge_dim": "cultural_folk",
    "difficulty": "L2",
    "evidence_audit": {
      "visible_facts": [
        "器皿表面为温润的紫红/红铜色基底",
        "金属表面密布分布不规则、带有金属光泽的金色/黄褐色结晶斑纹（斑花）",
        "器型均为中式传统锻铸造形（香炉、花瓶、生肖摆件等）"
      ],
      "anchor_features": [
        "云南斑铜特有的红铜基底衬金色结晶斑块（红中显斑、斑中现亮）",
        "金属器物表面抛光后的自然晶体反光质感"
      ],
      "trigger_check": "能。斑铜为国家级非遗名录中极具辨识度的金属工艺，具备世界知识的模型能够准确检索出其独特的结晶斑纹特征，而非生成普通青铜或黄铜。",
      "counterexample_test": "弱模型易将斑铜绘制为普通素面黄铜炉、生有绿色铜锈的古青铜炉，或均匀无斑的纯紫铜炉。通过检验表面是否存在特有的金属结晶斑花，可有效过滤此类错误画面。"
    },
    "gen_prompt": "一张微距特写静物摄影：在斜射自然光照耀的古朴实木茶几上，端放着一件采用云南传统非遗斑铜技艺精制的仿古三足香炉，炉内正袅袅升起一缕纤细淡雅的青烟。器物轮廓沉稳端庄，表面反射着温润独特的金属质感，景深浅柔，背景虚化。",
    "implicit_checks": [
      {
        "check": "器物表面材质呈现典型的斑铜外观，即紫红或红铜色底面上密布不规则的金色/亮色结晶斑块",
        "knowledge": "[solid] 云南斑铜（国家级非遗）工艺核心特征为生铜/特种铜合金经锻打烧斑后，表面呈现紫红底色与金黄色结晶斑花相映的视觉效果",
        "verified": true,
        "weight": 0.5,
        "rubric": {
          "0": "器物为均一单色铜（纯黄铜/纯红铜）或布满青绿色铜锈的仿古青铜，无任何斑花结晶",
          "1": "表面有斑驳痕迹或污渍感，但呈现为人工杂色喷涂/印刷斑点，缺乏金属天然结晶的光泽层次",
          "2": "红铜/紫铜色基底下清晰呈现形态自然、大小不一且具金属反光的金色结晶斑块"
        },
        "acceptable_variants": [
          "结晶斑块呈金黄、橙黄或亮褐色",
          "香炉为带盖或无盖款式，表面斑花分布疏密自然"
        ]
      },
      {
        "check": "香炉为形制完整稳定的三足鼎立造型，端坐于茶几表面",
        "knowledge": "[solid] 中式仿古香炉典型形制之一为三足足鼎立结构，重心配比均衡",
        "verified": true,
        "weight": 0.3,
        "rubric": {
          "0": "香炉足部缺失、悬空、结构严重扭曲或不对称畸变",
          "1": "三足形态可见但比例失调，或接触面与茶几透视关系不够扎实",
          "2": "三足造型周正饱满，物理受力与台面贴合自然稳定"
        },
        "acceptable_variants": [
          "圆鼎形三足香炉",
          "鬲式或带耳的仿古三足香炉"
        ]
      },
      {
        "check": "一缕青烟从香炉口或盖孔自然升起，烟雾形态轻盈且与环境光照自洽",
        "knowledge": "[solid] 点燃香料产生的微量青烟受热空气上升气流影响，呈轻盈飘逸的流体形态",
        "verified": true,
        "weight": 0.2,
        "rubric": {
          "0": "未绘制烟气，或烟气粗重如浓烟、呈僵硬实心柱状",
          "1": "有烟气升起但边缘生硬或与炉口无连贯发生源关系",
          "2": "青烟细长柔美、半透明且形态符合室内微气流飘动规律"
        },
        "acceptable_variants": [
          "青烟垂直袅袅升起",
          "青烟随微风微有侧向飘散"
        ]
      }
    ],
    "facet_tags": [
      "cultural_elements",
      "material_texture",
      "lighting_atmosphere",
      "subject_prominence"
    ],
    "gate_spec": {
      "required_subjects": [
        "斑铜香炉"
      ],
      "theme_definition": "展示云南传统非遗斑铜材质与工艺美感的三足香炉静物特写"
    },
    "expected_failure_modes": [
      "将斑铜误解为青铜，生成满身绿锈（铜绿）的考古青铜器",
      "生成纯亮黄色的抛光黄铜香炉，完全缺失金色结晶斑纹特征",
      "斑点画成类似豹纹或波点印花的大面积规则图案，缺乏天然金属熔铸结晶的质感"
    ],
    "notes": "考察模型对云南非遗‘斑铜’这一中国传统特种金属材质的核心视觉认知（红铜基底+天然金斑），避免仅靠字面理解为普通铜器。"
  }
]
